// fillet-frame: an L block's concave inside edge rounded 4 mm
export function c008(context is Context, id is Id)
{
    fCuboid(context, id + "base", { "corner1" : vector(0, 0, 0) * millimeter, "corner2" : vector(30, 20, 10) * millimeter });
