    booleanBodies(context, id + "join", { "tools" : qUnion([qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), qBodyType(qCreatedBy(id + "riser", EntityType.BODY), BodyType.SOLID)]), "operationType" : BooleanOperationType.UNION });
    fillet(context, id + "round1", { "entities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(10, 10, 10) * millimeter)]), "radius" : 4 * millimeter });
